//! Exact clock planning for STM32 on the host (embedded_bedrock RCC-1).
//!
//! A board states its clock tree (oscillators, PLL dividers, prescalers, kernel muxes); the planner evaluates every
//! clock as an exact rational number, checks it against the reference manual, datasheet and errata (each limit names
//! the section it was read from), and writes `clocks.rs`: the register words `bedrock_clocks_rt` applies at boot and
//! the exact frequencies drivers use. The firmware build doesn't run the planner; `clocks.rs` is generated by the
//! `bedrock-clocks` CLI and committed next to the board's `clocks.toml`.
//!
//! Families: [h72x] (RM0468: STM32H723/733, H725/735, H730).

pub mod h72x;
pub mod ratio;
pub mod source;

pub use ratio::{Hz, Ratio};
pub use source::Source;

/// FNV-1a 64 of a file's bytes: the `source-hash` in a generated `clocks.rs` header, which a firmware's build
/// script compares without the planner (not a security hash).
pub fn source_hash(bytes: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for &b in bytes {
        h ^= b as u64;
        h = h.wrapping_mul(0x0000_0100_0000_01b3);
    }
    h
}
